import{_ as r,o as s,c as o,a3 as n}from"./chunks/framework.BWzgKoSO.js";const l=JSON.parse('{"title":"附 C　术语表","description":"","frontmatter":{},"headers":[],"relativePath":"appendix/c-glossary.md","filePath":"appendix/c-glossary.md","lastUpdated":1793337833000}'),p={name:"appendix/c-glossary.md"};function g(a,t,e,c,_,d){return s(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="附-c-术语表" tabindex="-1">附 C　术语表 <a class="header-anchor" href="#附-c-术语表" aria-label="Permalink to &quot;附 C　术语表&quot;">​</a></h1><p>按拼音排。每个词一句话，能懂就行，不背定义。</p><p><strong>BMI（体重指数）</strong>　体重（公斤）除以身高（米）的平方。中国标准：24～27.9 超重，28 以上肥胖〔G8，A〕。</p><p><strong>BMR（基础代谢率）</strong>　躺着不动、只维持呼吸心跳一天要烧掉的热量。占一天总消耗的大头。</p><p><strong>TDEE（每日总能量消耗）</strong>　BMR 乘活动系数，再加食物热效应。你在 2.3 算出来的那个数。</p><p><strong>GLP-1 受体激动剂</strong>　一类模拟肠道激素的药，作用是让你更早饱、饿得慢。司美格鲁肽、利拉鲁肽属于这一类。</p><p><strong>GIP/GLP-1 双靶点激动剂</strong>　同时作用于两个受体的药，替尔泊肽是代表。</p><p><strong>NEAT（非运动性活动产热）</strong>　走路、站着、做家务、抖腿这些不算运动的活动消耗的热量。一天能差几百千卡。</p><p><strong>TDEE 里的活动系数</strong>　把“你有多动”折成倍数的系数：久坐 1.2，轻度活动 1.375，中度 1.55，高度 1.725。</p><p><strong>大基数</strong>　体重明显偏高、BMI 通常 28 以上的人。这类人前期掉得快，但关节和心血管的负担也大，运动方式要挑。</p><p><strong>小基数</strong>　BMI 24 上下、体重不明显超标的人。这类人掉秤慢，重点在体脂率和围度，不在体重。</p><p><strong>去脂体重</strong>　体重减掉脂肪以后剩下的部分，包括肌肉、骨骼、内脏和水。减重时希望它别掉。</p><p><strong>平台期</strong>　连续三周平均体重不动，才叫平台期。一两周不动多数是水。</p><p><strong>热量缺口</strong>　一天吃进去的比消耗掉的少多少。减重唯一绕不过去的机制。</p><p><strong>静息代谢适应</strong>　长期减重后，身体在更低的消耗水平上运转，比按体重推算的更省。极端减重后可以持续好几年〔R12，B〕。</p><p><strong>蛋白质的“每公斤体重”口径</strong>　按体重算蛋白需要量，比如 1.6 克/公斤/天。这个口径和“占总热量百分比”不能混着比。</p><p><strong>供能比</strong>　蛋白质、脂肪、碳水各占总热量的百分比。减重期常见是蛋白 15%～20%、脂肪 20%～30%、碳水 50%～60%〔G1，A〕。</p><p><strong>GI（血糖生成指数）</strong>　某种含碳水的食物让血糖升多快。低 GI 不等于低热量，这是最容易搞混的一点。</p><p><strong>GL（血糖负荷）</strong>　GI 乘上实际碳水克数，比 GI 更贴近真实影响。</p><p><strong>生酮</strong>　把碳水压到极低、让身体靠酮体供能。短期掉秤快，掉的水多，长期依从性差。</p><p><strong>碳循环</strong>　按训练日高低调整碳水。目前没有针对减重结局的随机对照试验支持它比普通限热量更好（见 R10）。</p><p><strong>限时进食（16+8、TREAT）</strong>　把一天的进食压缩在固定时间窗里。效果主要来自总热量下降，不是时间窗本身。</p><p><strong>隔日禁食</strong>　一天正常吃、一天极低热量交替。在网状 meta 分析里，它是唯一比持续限热量略好的断食方案，平均多减 1.29 公斤〔R7，A〕。</p><p><strong>食物交换份</strong>　把同类食物按“一份 90 千卡”换算成可互换的份数。附 A 整张表就是它〔G1，A〕。</p><p><strong>低报</strong>　人记饮食时系统性地少记自己吃的东西，比例可以到两三成〔R3，B〕。这是记录法最大的误差来源。</p><p><strong>体重反弹</strong>　减下来的体重又长回去。指南在术后管理里把“比最低点反弹超过 15%”作为界定。</p><p><strong>肌少性肥胖</strong>　脂肪多、肌肉少同时存在。用减重药时尤其要防肌肉再掉。</p><p><strong>中心型肥胖</strong>　脂肪堆在腰腹。中国标准：男性腰围 ≥90 厘米，女性 ≥85 厘米〔G8，A〕。</p><p><strong>抗阻训练</strong>　对抗阻力练力量，哑铃、器械、自重都算。减重期的意义是保住肌肉。</p><p><strong>有氧运动</strong>　长时间、中低强度、靠氧气供能的运动，快走、慢跑、游泳、骑车。</p><p><strong>MET（代谢当量）</strong>　活动强度单位，1 MET 是静坐时的消耗。快走约 4 MET。</p><p><strong>可食部</strong>　去掉骨头、皮、籽、壳以后能吃的部分。营养表和交换表里的克数都是可食部。</p><p><strong>证据等级</strong>　这本书里 A、B、C 三档，标在每条结论后面，用来区分“官方文件说的”和“我猜的”。</p>',33)])])}const T=r(p,[["render",g]]);export{l as __pageData,T as default};
